 schema=dict(type='object',properties=dict(completed=dict(type='boolean'),pictures=dict(type='array',items=dict(type='object',properties=dict(box=dict(type='array',items=dict(type='number'),minItems=4,maxItems=4,description='Normalized x,y,width,height fractions of the supplied image.'),category=dict(type='string',enum=['PL','VE','FG','CE','OT']),note=dict(type='string')),required=['box','category','note'],additionalProperties=False))),required=['completed','pictures'],additionalProperties=False)
