 protocol=dict(version='PICTURE-RATING-AND-G6-G2-v1',frozen_utc=datetime.now(timezone.utc).isoformat(),release_status='AUTHORIZED_COLLECTION' if '--release' in sys.argv else 'PREPARED_NOT_RELEASED',authority='User requests two independent blind picture ratings in isolated per-page calls; apply frozen geometry; check G6/G2 before adjudication.',cohort_pages=168,planned_calls=336,models=dict(A='claude-sonnet-4-5-20250929',B='claude-opus-4-5-20251101'),provider='Installed Claude CLI normal existing authentication; no credential extraction or model tools.',cli_version='2.0.60',isolation='One new process, random neutral directory and new session UUID for each role/page. System prompt is identical manual, user content is exactly one image. Settings sources empty, all built-in tools disabled, MCP empty/strict, slash commands disabled. Sole model-visible tool is StructuredOutput response contract. No project history, text, geometry, source IDs, other page data, other rater responses or category expectations.',manual_sha256=sha(R/'MANUAL-RATER.md'),original_v41_manual_sha256=sha(V/'MANUAL.md'),response_schema_sha256=sha(R/'RESPONSE-SCHEMA.json'),image_sha256={t['task_id']:sha(V/'rater-only'/t['image']) for t in tasks},geometry_sha256=sha(geometry),source_geometry_freeze_sha256=sha(V/'registration/FINAL-REGISTRATION-FREEZE.json'),registered_physical_lines=1145,coordinate_units='Normalized fractions scaled to native canvas dimensions by analyst code, with no box repair/clipping or category edits.',distance='Euclidean rectangle edge-to-edge distance divided by the frozen line rectangle height. Nearest picture category at distance<=2 heights; otherwise NO. No pictures => NO.',ties='Min edge distance; then min center distance; then min box area; then lexicographic native geometry (x,y,w,h). No category priority and no dependence on output order. Exact coincident boxes with conflicting categories invalidate the page.',missing_or_invalid='Retain raw call and failure. Never invent NO for missing ratings or repair/rerate a completed response. No analyst follow-up prompts. No automatic retries of completed semantic responses. All original336 calls get one terminal attempt.',agreement='Cohen unweighted kappa before OT merge. G6 on PL/VE/FG/CE/OT/NO governs H-IMG; G2 on PL vs not-PL governs H-PLANT. Threshold exact kappa>=3/5, each independently. One physical line once, no H/F doubling. Pe=1 or no pairs => undefined, not perfect agreement. Primary gate requires paired labels on all1145 frozen registered lines; incomplete-pair kappa is diagnostic only.',adjudication='NOT AUTHORIZED HERE; no adjudication before G6/G2 receipts.',coordinate_control_limit='Synthetic outlined-square tests identified OT correctly but returned imprecise coordinates. These failures are retained; engineering schema tests do NOT qualify coordinate accuracy. Agreement between two models is not external annotation truth or a semantic result.',model_independence_limit='Distinct checkpoints and independent fresh call histories; shared training/provider may still produce correlated errors.',timing_exception='v4.2 was NOT frozen before initial registration. Retained45 and source registration timing exception persist. This rating freeze occurs before manuscript picture responses.',v103='PARKED',still_held=['support','scientific controls','outcome joins','H-IMG/H-PLANT tests','adjudication'],code_sha256={n:sha(R/n) for n in ['collect.py','agreement.py','verify_engineering.py']})
