 archive=R/'prior-permissions';archive.mkdir(exist_ok=True);shutil.copy2(V/'HOLD.json',archive/'HOLD-before-rating.json')
 permission=dict(status='RATING_AND_PRE_ADJUDICATION_G6_G2_ONLY',authority=protocol['authority'],rating_freeze_sha256=sha(R/'RATING-FREEZE.json'),collection_status=protocol['release_status'],allowed=['two independent picture-only ratings','apply frozen shared line geometry','G6/G2 before OT merge and adjudication'],still_held=protocol['still_held'],geometry_mutation='NOT AUTHORIZED',timing_exception=protocol['timing_exception'],v103='PARKED')
 save(V/'HOLD.json',permission);save(R/'AUTHORIZATION.json',permission)
